const tg = $('Telegram Message').first().json;
const msg = tg.message || tg.edited_message || {};
const chat = msg.chat || {};
const chatId = chat.id;
let text = String(msg.text || msg.caption || '').trim();
let viaVoice = false;
let transcribeTried = false;
if (!text) {
  try {
    const r = $('Transcribe Voice').first().json;
    transcribeTried = true;
    const cand = r && r.candidates && r.candidates[0];
    const parts = cand && cand.content && cand.content.parts;
    if (parts && parts.length) {
      text = String(parts[0].text || '').trim();
      viaVoice = text.length > 0;
    }
  } catch (e) { transcribeTried = false; }
}
if (!chatId) { return []; }
if (!text) {
  const why = transcribeTried
    ? '🎤 نتونستم صدا رو بشنوم — سرویس تبدیل گفتار جواب نداد. یک بار دیگه بفرست، یا همون را تایپ کن.'
    : '❓ چیزی برای خوندن پیدا نکردم. متن یا وویس بفرست.';
  return [{ json: { chatId: chatId, text: why, viaVoice: false, ok: false } }];
}
return [{ json: { chatId: chatId, text: text, viaVoice: viaVoice, ok: true } }];

