function normTarget(t) {
  const v = fa2en(t).toLowerCase().trim();
  if (!v || v === 'backlog' || v === 'بک‌لاگ' || v === 'بکلاگ') { return 'backlog'; }
  if (v === 'sprint' || v === 'current' || v === 'جاری') { return 'current'; }
  if (v === 'next' || v === 'بعدی') { return 'next'; }
  const m = v.match(/(\d+)/);
  return m ? m[1] : 'backlog';
}
function pickSprint(list, target) {
  const arr = (list || []).slice().sort(function (a, b) { return (a.id || 0) - (b.id || 0); });
  if (target === 'current') { return arr.filter(function (s) { return s.state === 'active'; })[0] || null; }
  if (target === 'next') { return arr.filter(function (s) { return s.state === 'future'; })[0] || null; }
  if (/^\d+$/.test(target)) {
    const hit = arr.filter(function (s) { const m = String(s.name || '').match(/(\d+)/); return m && m[1] === target; })[0];
    return hit || null;
  }
  return null;
}
function targetFa(t) { return t === 'backlog' ? 'بک‌لاگ' : (t === 'current' ? 'اسپرینت جاری' : (t === 'next' ? 'اسپرینت بعدی' : 'اسپرینت ' + t)); }
function cleanLabels(arr) { const out = []; for (const x of (Array.isArray(arr) ? arr : [])) { const c = LMAP[String(x).toLowerCase().trim()]; if (c && out.indexOf(c) === -1) { out.push(c); } } return out; }
let src = null;
try { const c = $('Check Approval').first().json; if (c && c.plan) { src = { plan: c.plan, chatId: c.chatId, byName: c.byName || '' }; } } catch (e) {}
if (!src) { try { const b = $('Read Button').first().json; const sdp = $getWorkflowStaticData('global'); src = { plan: sdp['plan_' + b.chatId], chatId: b.chatId, byName: b.byName || '' }; } catch (e) {} }
if (!src) { src = { plan: {}, chatId: null }; }
const o = src.plan || {};
const ISSUE = { 'Task':'10001', 'Bug':'10003' };
const subs = Array.isArray(o.subtasks) ? o.subtasks : [];
const u = who(o.assignee);
const labels = ['telegram'].concat(cleanLabels(o.labels));
const fields = {
  project: { key: 'PROJ' },
  issuetype: { id: ISSUE[o.issueType] || '10001' },
  summary: o.summaryEn,
  description: o.descriptionFa,
  labels: labels,
  priority: { id: PRIO[o.priority] || '3' }
};
if (u) { fields.assignee = { name: u }; }
if (subs.length === 0 && o.estimate) { fields.timetracking = { originalEstimate: o.estimate }; }
const want = normTarget(o.target);
let sprintId = null, sprintName = '', sprintMissed = '';
if (want !== 'backlog') {
  try {
    const sp = $('Fetch Active Sprint').first().json;
    const hit = pickSprint((sp && sp.values) ? sp.values : [], want);
    if (hit) { sprintId = hit.id; sprintName = hit.name; fields.customfield_10020 = hit.id; }
    else { sprintMissed = targetFa(want); }
  } catch (e) { sprintMissed = targetFa(want); }
}
return [{ json: { bodyJson: JSON.stringify({ fields: fields }), subtaskCount: subs.length, plan: o, labels: labels, assigneeName: u, sprintId: sprintId, sprintName: sprintName, sprintMissed: sprintMissed, chatId: src.chatId } }];

