function stepText(step, p) {
  p = p || {};
  const ls = (p.labels && p.labels.length) ? p.labels.join('، ') : '—';
  if (step === 'm') { return listText(p, p.__note); }
  if (step === 'sx') { return subText(p, Number(p.__sel) || 0); }
  if (step === 'st') { return '⏱ <b>تخمین جدید این ساب‌تسک:</b>'; }
  if (step === 'x') { return xText(p); }
  if (step === 'w') { return (p.__await === 'summaryEn') ? '📝 <b>عنوان جدید را بفرست</b> — انگلیسی.' : '📄 <b>توضیح جدید را بفرست</b> — فارسی.'; }
