const raw = String(b.arg || '');
const k = raw.slice(0, 1);
const v = raw.slice(2);
if (k === 'a') { plan.assignee = v; }
else if (k === 'l' && v !== 'done') { plan.labels = Array.isArray(plan.labels) ? plan.labels : []; const i = plan.labels.indexOf(v); if (i > -1) { plan.labels.splice(i, 1); } else { plan.labels.push(v); } }
else if (k === 'p') { plan.priority = PRIO_ID2[v] || 'Normal'; }
else if (k === 's') { plan.target = v; }
else if (k === 't') { plan.estimate = v; plan.subtasks = []; }
else if (k === 'b') { /* just go back */ }
else if (k === 'm') { if (v === 'p') { sel = 'p'; } else if (/^\d+$/.test(v)) { const i = Number(v) - 1; const ss = Array.isArray(plan.subtasks) ? plan.subtasks : []; if (ss[i]) { sel = i; } else { plan.__note = 'ساب‌تسک ' + v + ' وجود ندارد.'; } } }
else if (k === 'sx') { if (v === 't') { sd['wizfield_' + chatId] = 's:' + sel + ':summaryEn'; } else if (v === 'd') { sd['wizfield_' + chatId] = 's:' + sel + ':descriptionFa'; } }
else if (k === 'st') { const ss = Array.isArray(plan.subtasks) ? plan.subtasks : []; if (ss[Number(sel)]) { ss[Number(sel)].estimate = v; plan.subtasks = ss; } }
else if (k === 'x') { if (v === 't') { sd['wizfield_' + chatId] = 'summaryEn'; plan.__await = 'summaryEn'; } else if (v === 'd') { sd['wizfield_' + chatId] = 'descriptionFa'; plan.__await = 'descriptionFa'; } }
sd['wizsel_' + chatId] = sel;
plan.__sel = sel;
sd['plan_' + chatId] = plan;
let step = 'final';
const hasSubs = Array.isArray(plan.subtasks) && plan.subtasks.length > 0;
if (k === 'm') { step = (v === 'go') ? 'final' : ((v === 'p') ? 'x' : (plan.__note ? 'm' : 'sx')); if (plan.__note) { delete plan.__note; } }
else if (k === 'sx') { step = (v === 'e') ? 'st' : ((v === 'back') ? 'm' : 'w'); }
